#Bach Fantasia "Komm, heiliger Geist" BWV651 arranged for midi output on 9 channels
#by Robin Newman February 2017
# I played this on a Mac Book Pro by sending it to Logic Pro where it was voiced with a Church Organ software instrument
#reverb was added using the Space Designer plugin
#A separate version for Sonic Pi using built in synths is available
#based on a musescore by Clarin Pedro, with permission
#https://musescore.com/user/84251/scores/180151 
#requires SP 2.12.0-alpha-midi1
#use run_file "<path to BWV651-midi-RF>" to play
define :mplay do |notes,durs,channel|
  for x in 0..notes.length-1
    if notes[x].respond_to?(:each)
      notes[x].each do |n|
        midi n,dur: durs[x],channel: channel,vel: 80
      end
    else
      midi notes[x],dur: durs[x],channel: channel,vel: 80 #if notes[x] !=:r
    end
    sleep durs[x]
  end
end


